mapper.select:
SELECT 
    car.,
    c.COMPANY_NAME,
    s1.REAL_NAME AS ASSESSOR_NAME,
    s2.REAL_NAME AS CREATE_USER_NAME,
    s3.REAL_NAME AS UPDATE_USER_NAME
FROM TBL_CREDIT_ASSESSMENT_RECORD car
LEFT JOIN TBL_COMPANY c ON car.COMPANY_ID = c.ID
LEFT JOIN TBL_STAFF s1 ON car.ASSESSOR_ID = s1.STAFFID
LEFT JOIN TBL_STAFF s2 ON car.CREATEUSER = s2.STAFFID
LEFT JOIN TBL_STAFF s3 ON car.UPDATEUSER = s3.STAFFID

    car.ORGID = #{params.orgId}

        AND car.ASSESSMENT_NO LIKE CONCAT('%', #{params.assessmentNo}, '%')


        AND c.COMPANY_NAME LIKE CONCAT('%', #{params.companyName}, '%')


        AND car.ASSESSMENT_TYPE = #{params.assessmentType}


        AND car.ASSESSMENT_STATUS = #{params.assessmentStatus}


        AND car.CREDIT_RATING = #{params.creditRating}


        AND car.RISK_LEVEL = #{params.riskLevel}


        AND car.ASSESSOR_ID = #{params.assessorId}


        AND car.ASSESSMENT_DATE >= #{params.assessmentDateStart}


        AND car.ASSESSMENT_DATE <= #{params.assessmentDateEnd}


ORDER BY car.CREATETIME DESC

SELECT car., c.COMPANY_NAME, s1.REAL_NAME AS ASSESSOR_NAME FROM TBL_CREDIT_ASSESSMENT_RECORD car LEFT JOIN TBL_COMPANY c ON car.COMPANY_ID = c.ID LEFT JOIN TBL_STAFF s1 ON car.ASSESSOR_ID = s1.STAFFID
car.ORGID = #{params.orgId}
AND car.ASSESSMENT_TYPE = #{params.assessmentType}
AND car.ASSESSMENT_STATUS = #{params.assessmentStatus}
ORDER BY car.CREATETIME DESC

