FROM TBL_CREDIT_ASSESSMENT_RECORD
WHERE ASSESSMENT_NO = #{assessmentNo} AND ORGID = #{orgId}

SELECT COUNT(*)
FROM TBL_CREDIT_ASSESSMENT_RECORD
WHERE ASSESSMENT_NO = #{assessmentNo}
